package kr.blackwiki.smp;
import org.bukkit.Material;
import org.bukkit.configuration.file.YamlConfiguration;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class Update25Test {
    @TempDir Path dir;
    String defaults()throws Exception{try(var in=getClass().getResourceAsStream("/config.yml")){return new String(Objects.requireNonNull(in).readAllBytes(),StandardCharsets.UTF_8);}}
    @Test void migrationPreservesValuesAndUnrelatedData()throws Exception{Path file=dir.resolve("config.yml"),data=dir.resolve("data.yml");String original="queue:\n  player-slots: 71\n  max-waiting: 9\ndiscord:\n  enabled: true\n  webhook-url: old-private-url\ncustom-setting: keep-me\n";Files.writeString(file,original);Files.writeString(data,"coins: 123456\n");var result=UpgradeService.migrate(file,defaults());YamlConfiguration y=new YamlConfiguration();y.load(file.toFile());assertEquals(71,y.getInt("queue.player-slots"));assertEquals(9,y.getInt("queue.max-waiting"));assertEquals("keep-me",y.getString("custom-setting"));assertEquals("",y.getString("discord.bot-token"));assertEquals("bot",y.getString("discord.mode"));assertTrue(y.getBoolean("discord.enabled"));assertFalse(y.contains("discord.webhook-url"));assertEquals(40,y.getInt("config-version"));assertTrue(y.getBoolean("spawn-design.auto-create"));assertEquals(original,Files.readString(dir.resolve("config.yml.before-4.0.bak")));assertEquals("coins: 123456\n",Files.readString(data));assertTrue(result.changed());}
    @Test void migrationIsIdempotentAndKeepsEnteredBotToken()throws Exception{Path file=dir.resolve("config.yml");Files.writeString(file,"discord:\n  bot-token: unit-test-token-123456789\n  channel-id: '123456789'\n");UpgradeService.migrate(file,defaults());String once=Files.readString(file),backup=Files.readString(dir.resolve("config.yml.before-4.0.bak"));var second=UpgradeService.migrate(file,defaults());assertFalse(second.changed());assertEquals(once,Files.readString(file));assertEquals(backup,Files.readString(dir.resolve("config.yml.before-4.0.bak")));assertTrue(once.contains("unit-test-token-123456789"));}
    @Test void newerSchemaAndBrokenYamlAreNeverOverwritten()throws Exception{Path file=dir.resolve("config.yml");for(String content:List.of("config-version: 999\n","broken: [unclosed\n")){Files.writeString(file,content);assertThrows(Exception.class,()->UpgradeService.migrate(file,defaults()));assertEquals(content,Files.readString(file));assertFalse(Files.exists(dir.resolve("config.yml.before-4.0.bak")));}}
    @Test void botRouteAndTokenValidationCannotAcceptWebhooksOrHeaderInjection(){assertEquals("https://discord.com/api/v10/channels/123456789/messages",DiscordRelay.endpoint("123456789").toString());assertEquals("unit-test-token-123456789",DiscordRelay.token(" Bot unit-test-token-123456789 "));for(String value:List.of("https://discord.com/api/webhooks/123456789/token","1/../../users/@me","-1","","123 456"))assertThrows(IllegalArgumentException.class,()->DiscordRelay.endpoint(value));for(String value:List.of("short","https://example.com/token","unit-test-token-123456789\r\nExtra: header"))assertThrows(IllegalArgumentException.class,()->DiscordRelay.token(value));}
    @Test void botSettingsNeverPrintTokenAndPayloadHasNoWebhookIdentity(){String token="unit-test-token-123456789";assertFalse(new DiscordRelay.Settings(true,DiscordRelay.endpoint("123456789"),token,10,1000).toString().contains(token));var json=com.google.gson.JsonParser.parseString(DiscordRelay.payload("hello @everyone")).getAsJsonObject();assertFalse(json.has("username"));assertEquals(0,json.getAsJsonObject("allowed_mentions").getAsJsonArray("parse").size());}
    @Test void successfulRateLimitHeadersDelayNextMessage(){int[] requests={0};try(var relay=new DiscordRelay(new DiscordRelay.Settings(true,DiscordRelay.endpoint("123456789"),"unit-test-token-123456789",10,1000),(uri,token,body)->{requests[0]++;return new DiscordRelay.Reply(200,"{}",Map.of("x-ratelimit-remaining",List.of("0"),"x-ratelimit-reset-after",List.of("3.25")));},false)){relay.offer("first");relay.pump(0);relay.offer("second");relay.pump(3249);assertEquals(1,requests[0]);relay.pump(3250);assertEquals(2,requests[0]);}}
    @Test void botPermissionAndMissingChannelFailuresStopFlood(){for(int status:List.of(403,404)){int[] requests={0};try(var relay=new DiscordRelay(new DiscordRelay.Settings(true,DiscordRelay.endpoint("123456789"),"unit-test-token-123456789",10,1000),(uri,token,body)->{requests[0]++;return new DiscordRelay.Reply(status,"private response",Map.of());},false)){relay.offer("first");relay.pump(0);relay.pump(100000);assertEquals(1,requests[0]);assertFalse(relay.offer("next"));assertFalse(relay.state().contains("private response"));}}}
    @Test void spawnPlanIsExactlyOneHundredByOneHundredWithUniquePositions(){var plan=SpawnPlan.build();assertTrue(plan.size()>30000);Set<SpawnPlan.Pos> positions=new HashSet<>();Set<String> floor=new HashSet<>();int minX=100,maxX=-100,minZ=100,maxZ=-100;for(var v:plan){assertTrue(positions.add(new SpawnPlan.Pos(v.x(),v.y(),v.z())));minX=Math.min(minX,v.x());maxX=Math.max(maxX,v.x());minZ=Math.min(minZ,v.z());maxZ=Math.max(maxZ,v.z());assertTrue(v.y()>=-3&&v.y()<=11);if(v.y()==0)floor.add(v.x()+":"+v.z());}assertEquals(100,maxX-minX+1);assertEquals(100,maxZ-minZ+1);assertEquals(10000,floor.size());}
    @Test void spawnEntryAndCentralNpcHaveAirAndWaterComesLast(){var plan=SpawnPlan.build();assertTrue(plan.stream().noneMatch(v->v.x()==0&&(v.z()==0||v.z()==12)&&v.y()>=1&&v.y()<=2));boolean water=false;for(var v:plan){if(v.type()==Material.WATER)water=true;else assertFalse(water,"Place containment before fluids");}assertTrue(water);}
    @Test void allGardenLeavesPersistAndFourFountainsHaveWaterCaps(){var plan=SpawnPlan.build();assertTrue(plan.stream().filter(v->v.type().name().endsWith("_LEAVES")).allMatch(v->v.data()!=null&&v.data().contains("persistent=true")));for(int x:new int[]{-25,25})for(int z:new int[]{-25,25})assertTrue(plan.stream().anyMatch(v->v.x()==x&&v.z()==z&&v.y()==5&&v.type()==Material.WATER));assertTrue(plan.stream().noneMatch(v->Set.of(Material.LAVA,Material.FIRE,Material.TNT).contains(v.type())));}
}
